import 'package:flutter/material.dart';

/// Pixel-art Mexican cantina behind the game tables (assets/images/cantina, generated by
/// tool/pixelart/cantina.py). Nearest-neighbour scaling keeps the pixels crisp at any size;
/// a light shade on top keeps cards, seats and buttons readable over the busy scene.
class CantinaBackground extends StatelessWidget {
  final Widget child;

  /// 0 = the scene as drawn, 1 = black. Tables with lots of text want a bit more.
  final double shade;

  const CantinaBackground({super.key, required this.child, this.shade = 0.18});

  /// Same scene drawn twice: phones are about 20:9, PCs and tablets 16:9. The closest one is
  /// used so the shelves, the nopal and the guitar at the sides are never cropped.
  static const assetWide = 'assets/images/cantina/cantina_bg.png'; // 444x200
  static const asset16x9 = 'assets/images/cantina/cantina_bg_16x9.png'; // 356x200

  static String assetFor(Size size) => size.height > 0 && size.width / size.height >= 2.0 ? assetWide : asset16x9;

  @override
  Widget build(BuildContext context) {
    return Stack(
      fit: StackFit.expand,
      children: [
        const ColoredBox(color: Color(0xFF100809)),
        LayoutBuilder(
          builder: (context, c) => Image.asset(
            assetFor(c.biggest),
            fit: BoxFit.cover,
            filterQuality: FilterQuality.none,
            isAntiAlias: false,
            gaplessPlayback: true,
          ),
        ),
        if (shade > 0) ColoredBox(color: Colors.black.withValues(alpha: shade)),
        child,
      ],
    );
  }
}
